{"sql": "SELECT m.chembl_id, m.pref_name, cs.canonical_smiles, m.max_phase, dm.mechanism_of_action, dm.action_type, t.chembl_id AS target_chembl_id, t.pref_name AS target_name FROM molecule_dictionary m JOIN drug_mechanism dm ON m.molregno = dm.molregno JOIN target_dictionary t ON dm.tid = t.tid JOIN compound_structures cs ON m.molregno = cs.molregno WHERE m.max_phase = 4 AND dm.action_type = 'POSITIVE ALLOSTERIC MODULATOR' ORDER BY m.chembl_id, m.pref_name, cs.canonical_smiles, m.max_phase, dm.mechanism_of_action, dm.action_type, t.chembl_id, t.pref_name"}
